import{_ as t}from"./chunks/29.mN_qNvEw.js";import{_ as a}from"./chunks/2.BRgDBKom.js";import{_ as o,o as i,c as n,am as r}from"./chunks/framework.CenUaW7a.js";const s="/projects/AiMechaM1/en/advanced-kit/assets/27.D-5nx30z.png",l="/projects/AiMechaM1/en/advanced-kit/assets/28.DzS_ay2f.png",c="/projects/AiMechaM1/en/advanced-kit/assets/30.PqD8yKws.png",p="/projects/AiMechaM1/en/advanced-kit/assets/31.C-DJIplx.png",d="/projects/AiMechaM1/en/advanced-kit/assets/32.B4O-WkxW.png",h="/projects/AiMechaM1/en/advanced-kit/assets/33.BTJQICzz.png",g="/projects/AiMechaM1/en/advanced-kit/assets/34.BQZqPC0Z.png",m="/projects/AiMechaM1/en/advanced-kit/assets/35.BpxRzvSP.png",u="/projects/AiMechaM1/en/advanced-kit/assets/36.DUXg5dIP.png",f="/projects/AiMechaM1/en/advanced-kit/assets/37.B8Q6aLOg.png",I=JSON.parse('{"title":"3.15 Lesson 15: Multi-Layer Gripping Training","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.15 Lesson 15 Multi-Layer Grasping Training.md","filePath":"docs/3. Course materials/3.15 Lesson 15 Multi-Layer Grasping Training.md"}'),v={name:"docs/3. Course materials/3.15 Lesson 15 Multi-Layer Grasping Training.md"};function b(w,e,y,k,_,x){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-15-lesson-15-multi-layer-gripping-training" tabindex="-1">3.15 Lesson 15: Multi-Layer Gripping Training <a class="header-anchor" href="#_3-15-lesson-15-multi-layer-gripping-training" aria-label="Permalink to &quot;3.15 Lesson 15: Multi-Layer Gripping Training&quot;">​</a></h1><h2 id="_3-15-1-lesson-introduction" tabindex="-1">3.15.1 Lesson Introduction <a class="header-anchor" href="#_3-15-1-lesson-introduction" aria-label="Permalink to &quot;3.15.1 Lesson Introduction&quot;">​</a></h2><p>Building upon basic manipulation and in-place grasping from the previous two lessons, this third lesson in the robotic arm series focuses on multi-level grasping of objects at different heights. Adding a vertical height dimension to planar grasping, the robotic arm adjusts its grasping parameters according to the object height and coordinates with the movement of the Mecanum-wheel car to pick up blocks from different heights and place them in a designated area.</p><p>Inspired by warehouse palletizing operations, this lesson highlights the importance of height and positional accuracy. Analyzing the positions of high and low blocks determines the corresponding servo angles across four progressive tasks, including variable definition and function encapsulation. The core project coordinates the Mecanum-wheel car and the robotic arm to grasp and return blocks from high and low platforms, practicing parameterized programming, variable operations, height parameter tuning, and chassis-arm coordination in preparation for distance measurement and vision sorting lessons.</p><h2 id="_3-15-2-learning-objectives" tabindex="-1">3.15.2 Learning Objectives <a class="header-anchor" href="#_3-15-2-learning-objectives" aria-label="Permalink to &quot;3.15.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand how to determine the command parameters for positioning the robotic arm at different heights, and master the relationship between the angular positions of servo ID 2 and servo ID 3 and the resulting grasping height. Understand the role of variables in programming and master how to define, assign, and call variables.</p><p><strong>2.</strong> Tune the angular position parameters of servo ID 2 and servo ID 3 according to object height. Use variables to store servo angular positions for flexible switching between grasping parameters at different heights. Encapsulate custom functions for picking from a platform and placing at the same location.</p><p><strong>3.</strong> Develop a parameterized programming mindset by using variables instead of fixed numerical values to make programs more flexible and versatile. Build multi-level task decomposition skills to break down complex multi-height grasping tasks into independent picking and placing modules.</p><p><strong>4.</strong> Connect multi-level grasping technology to practical application scenarios such as logistics warehouse palletizing, factory material loading and unloading, and library book sorting. Understand the practical value of parameterized programming in adapting automated equipment to objects of varying specifications.</p><h2 id="_3-15-3-preparation" tabindex="-1">3.15.3 Preparation <a class="header-anchor" href="#_3-15-3-preparation" aria-label="Permalink to &quot;3.15.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-wheel robot base × 1</li><li>Type-C USB data cable × 1</li><li>Computer running Windows or macOS × 1</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running properly</li></ul><p><strong>Key Parameter Description:</strong></p><ul><li><p>Low-position small block: Located 3.5 cm above the reference plane at a distance of 10 cm from the Mecanum-wheel car, with the angular position of servo ID 2 set to 800 and servo ID 3 set to 500.</p></li><li><p>High-position small block: Located 9.5 cm above the reference plane on a 9.5 cm platform at a distance of 10 cm from the Mecanum-wheel car, with the angular position of servo ID 2 set to 900 and servo ID 3 set to 400.</p></li><li><p>The angular positions of servo ID 2 and servo ID 3 above serve as reference values and can be adjusted according to the actual placement locations.</p></li><li><p>In-place 90° rotation of the Mecanum-wheel car is achieved by configuring the rotational speeds and wait time.</p></li></ul><h2 id="_3-15-4-hands-on-project" tabindex="-1">3.15.4 Hands-On Project <a class="header-anchor" href="#_3-15-4-hands-on-project" aria-label="Permalink to &quot;3.15.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Program Logic</strong></p><p>This program implements multi-level grasping and unified placement by configuring servo angles for high and low positions using parameterized variables. After the Mecanum-wheel car moves into position, the robotic arm adjusts its height according to the variable values to grasp the block and transport it to a fixed location for placement. By encapsulating the picking and placing functions, the main program sequentially calls the low-position and high-position tasks, completing multi-height block handling and unified placement while improving code reusability.</p><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Variable operation</td><td style="text-align:center;"><img loading="lazy" height="344" width="384" src="'+s+'" class="common_img" style="width:260px;aspect-ratio:384 / 344;"></td><td style="text-align:left;">Defines angular position variables for servo ID 2 and servo ID 3, assigning different parameter values according to target heights.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="92" width="647" src="'+l+'" class="common_img" style="width:400px;aspect-ratio:647 / 92;"></td><td style="text-align:left;">Uses variables to control the forward extension and backward retraction of the robotic arm, dynamically adjusting variable values based on grasping height.</td></tr><tr><td style="text-align:center;">Servo control</td><td style="text-align:center;"><img loading="lazy" height="53" width="534" src="'+t+'" class="common_img" style="width:400px;aspect-ratio:534 / 53;"></td><td style="text-align:left;">Controls the mechanical gripper to open and close for grasping and releasing actions.</td></tr><tr><td style="text-align:center;">Motor control</td><td style="text-align:center;"><img loading="lazy" height="202" width="547" src="'+c+'" class="common_img" style="width:400px;aspect-ratio:547 / 202;"></td><td style="text-align:left;">Controls the Mecanum-wheel car to move forward, backward, and laterally toward different platforms and placement areas.</td></tr><tr><td style="text-align:center;">Motor control</td><td style="text-align:center;"><img loading="lazy" height="61" width="480" src="'+p+'" class="common_img" style="width:400px;aspect-ratio:480 / 61;"></td><td style="text-align:left;">Controls the Mecanum-wheel car to rotate 90° in place, adjusting its heading to align with different platforms or placement areas.</td></tr><tr><td style="text-align:center;">Function encapsulation</td><td style="text-align:center;"><img loading="lazy" height="348" width="716" src="'+d+'" class="common_img" style="width:400px;aspect-ratio:716 / 348;"></td><td style="text-align:left;">Encapsulates the complete sequence of lowering→ grasping → raising the robotic arm, using variable parameters to adapt to different heights.</td></tr><tr><td style="text-align:center;">Function encapsulation</td><td style="text-align:center;"><img loading="lazy" height="362" width="720" src="'+h+'" class="common_img" style="width:460px;aspect-ratio:720 / 362;"></td><td style="text-align:left;">Encapsulates the placement sequence of lowering → releasing → raising the robotic arm to place all blocks at the same location.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Setting the Angular Positions of Servo ID 2 and Servo ID 3 as Variables</strong></p><ul><li><p>Building upon the program from the previous lesson, define two variables: <code>servo 2 position</code> and <code>servo 3 position</code>.</p></li><li><p>Because the lowering angle of the robotic arm varies when picking up small blocks from platforms of different heights, variables are used to dynamically store the angular values.</p></li><li><p>Initialize the variables with the low-position grasping parameters by setting <code>servo 2 position</code> to 800 and <code>servo 3 position</code> to 500.</p></li><li><p>Assign the corresponding angular values to the variables before executing grasping maneuvers at different heights.</p></li></ul><img loading="lazy" height="601" width="563" src="'+g+'" class="common_img" style="width:490px;aspect-ratio:563 / 601;"><p><strong>Task 2: Encapsulating Functions for Picking from a Platform and Placing at the Same Location</strong></p><ul><li><p>Define the <code>Grab From Platform</code> function: Extend servo ID 2 forward to its variable value position → lower servo ID 3 to its variable value position → wait → close servo ID 1 to grasp the block → wait → raise servo ID 3 → retract servo ID 2.</p></li><li><p>Define the <code>Place At Same Position</code> function: Extend servo ID 2 forward to the placement position → lower servo ID 3 to the placement height → open servo ID 1 to release the block → wait → raise servo ID 3 → retract servo ID 2 to return to the initial position.</p></li><li><p>Both functions use variables to control key angles, allowing a single set of code to adapt to different heights.</p></li></ul><img loading="lazy" height="476" width="480" src="'+m+'" class="common_img" style="width:490px;aspect-ratio:480 / 476;"><p><strong>Task 3: Picking Up a Small Block from a Low Position and Placing It at a Specified Location</strong></p><ul><li><p>Set the low-position parameters by assigning <code>Servo 2 Position</code> to 800 and <code>Servo 3 Position</code> to 500.</p></li><li><p>Move the Mecanum-wheel car in front of the low platform, maintaining a distance of approximately 10 cm.</p></li><li><p>Call the <code>Grab From Platform</code> function to grasp the small block located 3.5 cm above the reference plane.</p></li><li><p>Move the Mecanum-wheel car to the unified placement area.</p></li><li><p>Call the <code>Place At Same Position</code> function to place the block at the designated position.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p></p><p><strong>The angular positions of servo ID 2 and servo ID 3 can be adjusted according to the actual placement locations.</strong></p></div><img loading="lazy" height="451" width="477" src="'+u+'" class="common_img" style="width:460px;aspect-ratio:477 / 451;"></li></ul><p><strong>Task 4: Picking Up a Small Block from a High Position and Placing It at a Specified Location</strong></p><ul><li><p>Set the high-position parameters by assigning <code>Servo 2 Position</code> to 900 and <code>Servo 3 Position</code> to 400.</p></li><li><p>Move the Mecanum-wheel car in front of the high platform, maintaining a distance of approximately 10 cm.</p></li><li><p>Call the <code>Grab From Platform</code> function to grasp the small block on the 9.5 cm platform.</p></li><li><p>Move the Mecanum-wheel car to the unified placement area.</p></li><li><p>Call the <code>Place At Same Position</code> function to place the block at the same location as the low-position block.</p></li><li><p>Similarly, the angular positions of servo ID 2 and servo ID 3 can be adjusted according to the actual placement locations.</p></li><li><p>Finally, integrate Task 3 and Task 4 to sequentially pick up small blocks from different heights and place them at a unified location.</p></li></ul><img loading="lazy" height="450" width="470" src="'+f+'" class="common_img" style="width:460px;aspect-ratio:470 / 450;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Line Following Intersection Feedback</a>.</strong></p></div><p><strong>Program Upload:</strong></p><ul><li>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</li><li>Step 2: Connect the other end of the data cable to a USB port on the computer.</li><li>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</li><li>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</li></ul><img loading="lazy" height="508" width="960" src="'+a+'" class="common_img" style="width:800px;aspect-ratio:960 / 508;"><h2 id="_3-15-5-expansion-and-advancement" tabindex="-1">3.15.5 Expansion and Advancement <a class="header-anchor" href="#_3-15-5-expansion-and-advancement" aria-label="Permalink to &quot;3.15.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Multi-Height Stepped Grasping and Rotational Placement</strong></p><p>Expand the task to three-tiered stepped grasping by using arrays to manage multiple sets of height parameters. Drive the Mecanum-wheel car sequentially to each tier, grasp the block, and rotate 90° in place to place the blocks at the front, left, and right positions, respectively. This project focuses on data structure application and multi-task scheduling, requiring precise control over vehicle movement and steering.</p><p><strong>Project 2: Automatic Grasping Height Measurement and Parameter Adaptation</strong></p><p>Integrate the ultrasonic sensor to achieve automatic height measurement and adaptive grasping. Slowly lower the robotic arm from a high position while monitoring the distance in real time, recording the servo angle as the grasping height whenever a sudden distance change occurs. Using a height search algorithm links sensor data with actuator movements, replacing manually preset parameters.</p><h2 id="_3-15-6-q-a" tabindex="-1">3.15.6 Q&amp;A <a class="header-anchor" href="#_3-15-6-q-a" aria-label="Permalink to &quot;3.15.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: Which servo IDs need their angles adjusted when grasping at different heights, and why?</strong></p><p><strong>Answer</strong>: Adjusting servo ID 2 and servo ID 3 requires coordinated tuning. Due to the mechanical linkage structure, changing the vertical height via servo ID 3 simultaneously affects the horizontal reach of the gripper, requiring a synchronized adjustment to the forward extension of servo ID 2 to compensate for the horizontal displacement. For example, low-position grasping sets servo ID 2 to 800 and servo ID 3 to 500, whereas high-position grasping sets servo ID 2 to 900 and servo ID 3 to 400. Only by varying both parameters together can the mechanical gripper accurately reach the target point, whereas adjusting a single servo cannot balance both height and horizontal distance.</p><p><strong>Q2: How is the in-place 90° rotation of the Mecanum-wheel car achieved, and what parameters need to be configured?</strong></p><p><strong>Answer</strong>: In-place 90° rotation of the Mecanum-wheel car is achieved through four-wheel differential speed control, where rotating the left and right motors in opposite directions generates rotational torque. Because open-loop control is affected by ground friction, the rotation angle is indirectly controlled by &quot;setting the rotational speed + tuning the wait time&quot;. Estimate the duration first before fine-tuning through field testing, or introduce an IMU gyroscope for closed-loop feedback to eliminate errors and ensure an accurate 90° rotation.</p><h2 id="_3-15-7-technical-support-and-discussion" tabindex="-1">3.15.7 Technical Support and Discussion <a class="header-anchor" href="#_3-15-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.15.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',49)])])}const S=o(v,[["render",b]]);export{I as __pageData,S as default};
